// Pipelining constants
const PIPELINE_STATUS = {
    IDLE: 'idle',
    RUNNING: 'running',
    COMPLETED: 'completed',
    FAILED: 'failed'
};

// Pipelining class
class Pipeline {
    constructor(name) {
        this.name = name;
        this.status = PIPELINE_STATUS.IDLE;
        this.steps = [];
    }

    addStep(step) {
        this.steps.push(step);
        return this;
    }

    run() {
        this.status = PIPELINE_STATUS.RUNNING;
        console.log(`Pipeline ${this.name} is running`);
        return this;
    }
}

// Pipelining middleware
function pipelineMiddleware(req, res, next) {
    res.setHeader('X-Pipeline-Status', 'active');
    next();
}

// Pipelining configuration object
const pipelineOptions = {
